	@Test
	void recordsValueOrderAndPhysicalJoinRepresentatives() {
		Literal upper = VF.createLiteral("label", "EN");
		Literal lower = VF.createLiteral("label", "en");
		TripleSource source = new EmptySource();
		Join originalJoin = new Join(values(upper, lower), values(upper));
		Filter originalFilter = languageFilter(originalJoin);
		List<BindingSet> rawJoinRows = evaluate(source, originalJoin, EmptyBindingSet.getInstance());
		List<BindingSet> rawFilteredRows = evaluate(source, originalFilter, EmptyBindingSet.getInstance());

		TupleExpr joinOptimized = new QueryRoot(originalJoin.clone());
		new QueryJoinOptimizer(new EvaluationStatistics()).optimize(joinOptimized, null,
				EmptyBindingSet.getInstance());

		TupleExpr fullyOptimized = new QueryRoot(languageFilter(originalJoin.clone()));
		StrictEvaluationStrategy fullStrategy = new StrictEvaluationStrategy(source, null);
		fullStrategy.optimize(fullyOptimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		List<BindingSet> fullRows;
		try (CloseableIteration<BindingSet> rows = fullStrategy.precompile(fullyOptimized)
				.evaluate(EmptyBindingSet.getInstance())) {
			fullRows = collect(rows);
		}
		Join fullyOptimizedJoin = firstJoin(fullyOptimized);

		List<String> hashLeft = evaluateForcedHash(source, upper, lower, "left");
		List<String> hashRight = evaluateForcedHash(source, upper, lower, "right");

		System.out.println("join representative routes"
				+ "\n  raw join reps=" + representatives(rawJoinRows, upper, lower)
				+ "\n  raw Filter(LANG(x)=EN) reps=" + representatives(rawFilteredRows, upper, lower)
				+ "\n  after QueryJoinOptimizer:\n" + joinOptimized
				+ "\n  full optimized:\n" + fullyOptimized
				+ "\n  full algorithm=" + fullyOptimizedJoin.getAlgorithmName()
				+ " full reps=" + representatives(fullRows, upper, lower)
				+ "\n  forced HashJoinIteration build-left reps=" + hashLeft
				+ "\n  forced HashJoinIteration build-right reps=" + hashRight);

		assertThat(rawJoinRows).hasSize(2);
		assertThat(rawFilteredRows).hasSize(1);
		assertThat(fullRows).hasSize(2);
		assertThat(representatives(fullRows, upper, lower))
				.containsExactlyElementsOf(representatives(rawFilteredRows, upper, lower));
		assertThat(fullyOptimizedJoin.getAlgorithmName()).isEqualTo("JoinIterator");
		assertThat(hashLeft).containsExactly("upper@EN");
		assertThat(hashRight).containsExactly("upper@EN");
	}

	@Test
	void recordsStatementPatternJoinRepresentativesAcrossNestedLoopHashAndMerge() {
		Literal upper = VF.createLiteral("label", "EN");
		Literal lower = VF.createLiteral("label", "en");
		IRI leftPredicate = VF.createIRI("urn:join:left");
		IRI rightPredicate = VF.createIRI("urn:join:right");
		assertThat(upper).isEqualTo(lower);
		assertThat(new ValueComparator().compare(upper, lower)).isNegative();
		TripleSource source = new OrderedSource(upper, lower, leftPredicate, rightPredicate);
		Join original = statementJoin(leftPredicate, rightPredicate);
		List<String> nestedLoop = representatives(evaluate(source, original, EmptyBindingSet.getInstance()), upper,
				lower);

		TupleExpr optimized = new QueryRoot(statementJoin(leftPredicate, rightPredicate));
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		strategy.optimize(optimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		Join optimizedJoin = firstJoin(optimized);
		List<BindingSet> mergeRows;
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(optimized)
				.evaluate(EmptyBindingSet.getInstance())) {
			mergeRows = collect(iteration);
		}
		List<String> merge = representatives(mergeRows, upper, lower);

		List<String> hashLeft = evaluateStatementHash(source, leftPredicate, rightPredicate, "left", upper, lower);
		List<String> hashRight = evaluateStatementHash(source, leftPredicate, rightPredicate, "right", upper, lower);
		List<String> arrayHashLeft = evaluateArrayHash(upper, lower, HashJoinIteration.BuildSide.LEFT);
		List<String> arrayHashRight = evaluateArrayHash(upper, lower, HashJoinIteration.BuildSide.RIGHT);

		System.out.println("statement join representative routes"
				+ "\n  optimized tree:\n" + optimized
				+ "\n  selected optimized algorithm=" + optimizedJoin.getAlgorithmName()
				+ " merge candidate=" + optimizedJoin.isMergeJoin()
				+ " nested-loop reps=" + nestedLoop
				+ "\n  optimized reps=" + merge
				+ "\n  forced hash build-left reps=" + hashLeft
				+ "\n  forced hash build-right reps=" + hashRight
				+ "\n  array hash build-left reps=" + arrayHashLeft
				+ "\n  array hash build-right reps=" + arrayHashRight);

		assertThat(optimizedJoin.isMergeJoin()).isTrue();
		assertThat(optimizedJoin.getAlgorithmName()).isEqualTo("InnerMergeJoinIterator");
		assertThat(nestedLoop).containsExactly("upper@EN", "lower@en");
		assertThat(merge).containsExactly("upper@EN", "lower@en");
		assertThat(hashLeft).containsExactlyElementsOf(nestedLoop);
		assertThat(hashRight).containsExactlyElementsOf(nestedLoop);
		assertThat(arrayHashLeft).containsExactlyElementsOf(nestedLoop);
		assertThat(arrayHashRight).containsExactlyElementsOf(nestedLoop);
	}

