	@Test
	void nullableDefaultContextIsNotACompleteMergeKeyAndBoundInputsRemainExact() {
		IRI leftPredicate = VF.createIRI("urn:join:context-left");
		IRI rightPredicate = VF.createIRI("urn:join:context-right");
		Resource firstGraph = VF.createIRI("urn:join:graph-a");
		Resource secondGraph = VF.createIRI("urn:join:graph-b");
		Resource requestedGraph = VF.createIRI("urn:join:graph-c");
		ContextOrderedSource source = new ContextOrderedSource(leftPredicate, rightPredicate,
				java.util.Arrays.asList(null, firstGraph, secondGraph), List.of(secondGraph));
		Join original = contextJoin(leftPredicate, rightPredicate);
		List<BindingSet> ordinary = evaluate(source, original, EmptyBindingSet.getInstance());
		System.out.println("nullable default-context raw route"
				+ "\n  left supported orders=" + original.getLeftArg().getSupportedOrders(source)
				+ "\n  ordinary bag=" + bindingValues(ordinary, "g"));
		assertThat(bindingValues(ordinary, "g")).containsExactly("urn:join:graph-b");

		TupleExpr optimized = new QueryRoot(original.clone());
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		strategy.optimize(optimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		Join optimizedJoin = firstJoin(optimized);
		List<BindingSet> optimizedRows = evaluatePrepared(strategy, optimized, EmptyBindingSet.getInstance());

		System.out.println("nullable default-context merge key"
				+ "\n  supported orders=" + original.getLeftArg().getSupportedOrders(source)
				+ "\n  selected algorithm=" + optimizedJoin.getAlgorithmName()
				+ "\n  ordinary bag=" + bindingValues(ordinary, "g")
				+ "\n  optimized bag=" + bindingValues(optimizedRows, "g"));

		assertThat(bindingValues(ordinary, "g")).containsExactly("urn:join:graph-b");
		assertThat(optimizedJoin.isMergeJoin()).isFalse();
		assertThat(bindingValues(optimizedRows, "g")).containsExactlyElementsOf(bindingValues(ordinary, "g"));

		BindingSet bound = new ListBindingSet(List.of("g"), secondGraph);
		BindingSet absent = new ListBindingSet(List.of("g"), requestedGraph);
		List<BindingSet> boundOrdinary = evaluate(source, original, bound);
		List<BindingSet> boundOptimized = evaluatePrepared(strategy, optimized, bound);
		List<BindingSet> absentOrdinary = evaluate(source, original, absent);
		List<BindingSet> absentOptimized = evaluatePrepared(strategy, optimized, absent);

		assertThat(bindingValues(boundOrdinary, "g")).containsExactly("urn:join:graph-b");
		assertThat(bindingValues(boundOptimized, "g")).containsExactlyElementsOf(bindingValues(boundOrdinary, "g"));
		assertThat(absentOrdinary).isEmpty();
		assertThat(absentOptimized).isEmpty();
	}

	@Test
	void opaqueOrderedAssignmentInsideNestedJoinCannotCertifyOuterMergeKey() {
		Literal upper = VF.createLiteral("label", "EN");
		Literal lower = VF.createLiteral("label", "en");
		IRI leftPredicate = VF.createIRI("urn:join:opaque-left");
		IRI rightPredicate = VF.createIRI("urn:join:opaque-right");
		OrderedSource source = new OrderedSource(List.of(upper, lower), List.of(upper), leftPredicate, rightPredicate);
		BindingSetAssignment opaque = opaqueOrderedAssignment(lower);
		Join nested = new Join(opaque, statementPattern(leftPredicate));
		Join original = new Join(nested, statementPattern(rightPredicate));
		List<String> ordinary = representatives(evaluate(source, original, EmptyBindingSet.getInstance()), upper,
				lower);

		TupleExpr optimized = new QueryRoot(original.clone());
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		strategy.optimize(optimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		List<Join> optimizedJoins = joins(optimized);
		List<String> optimizedValues = representatives(evaluatePrepared(strategy, optimized,
				EmptyBindingSet.getInstance()), upper, lower);
		TupleExpr forced = new QueryRoot(original.clone());
		Join forcedOuter = firstJoin(forced);
		forcedOuter.setMergeJoin(true);
		forcedOuter.setOrder(Var.of("x"));
		List<String> forcedValues = representatives(evaluatePrepared(strategy, forced,
				EmptyBindingSet.getInstance()), upper, lower);

		System.out.println("opaque ordered assignment merge-key proof"
				+ "\n  optimized tree:\n" + optimized
				+ "\n  join algorithms=" + optimizedJoins.stream().map(Join::getAlgorithmName).toList()
				+ "\n  ordinary bag=" + ordinary
				+ "\n  optimized bag=" + optimizedValues
				+ "\n  experimental pre-marked-model/cached-plan boundary algorithm=" + forcedOuter.getAlgorithmName()
				+ " forced bag=" + forcedValues);

		assertThat(opaque.getBindingNames()).isEmpty();
		assertThat(opaque.hasRepeatableBindingSets()).isFalse();
		assertThat(ordinary).containsExactly("lower@en", "lower@en");
		assertThat(optimizedJoins).allSatisfy(join ->
				assertThat(join.getAlgorithmName()).isNotEqualTo("InnerMergeJoinIterator"));
		assertThat(optimizedValues).containsExactlyElementsOf(ordinary);
		assertThat(forcedValues).containsExactlyElementsOf(ordinary);
		assertThat(forcedOuter.getAlgorithmName()).isNotEqualTo("InnerMergeJoinIterator");
	}

	@Test
	void projectionAliasWithBoundSourceHasNoNaturalMergeOrder() {
		Literal upper = VF.createLiteral("label", "EN");
		Literal lower = VF.createLiteral("label", "en");
		IRI leftPredicate = VF.createIRI("urn:join:alias-left");
		IRI rightPredicate = VF.createIRI("urn:join:alias-right");
		OrderedSource source = new OrderedSource(List.of(upper, lower), List.of(upper), leftPredicate, rightPredicate);
		StatementPattern pattern = new StatementPattern(Var.of("leftSubject"), Var.of("leftPredicate", leftPredicate),
				Var.of("source"));
		Projection left = new Projection(pattern,
				new ProjectionElemList(new ProjectionElem("source", "x")));
		Join original = new Join(left, statementPattern(rightPredicate));
		BindingSet input = new ListBindingSet(List.of("source"), lower);
		List<String> ordinary = representatives(evaluate(source, original, input), upper, lower);

		TupleExpr optimized = new QueryRoot(original.clone());
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		strategy.optimize(optimized, new EvaluationStatistics(), input);
		Join optimizedJoin = firstJoin(optimized);
		List<String> optimizedValues = representatives(evaluatePrepared(strategy, optimized, input), upper, lower);

		System.out.println("projection alias source/order route"
				+ "\n  projection output target=x; child source=source; invocation binds source"
				+ "\n  natural algorithm=" + optimizedJoin.getAlgorithmName()
				+ "\n  ordinary bag=" + ordinary
				+ "\n  optimized bag=" + optimizedValues);

		assertThat(input.hasBinding("x")).isFalse();
		assertThat(input.hasBinding("source")).isTrue();
		assertThat(ordinary).containsExactly("lower@en", "lower@en");
		assertThat(optimizedJoin.isMergeJoin()).isFalse();
		assertThat(optimizedValues).containsExactlyElementsOf(ordinary);
	}

	@Test
	void projectionAliasWithHiddenSourceParameterDoesNotSelectMerge() {
		Literal upper = VF.createLiteral("label", "EN");
		Literal lower = VF.createLiteral("label", "en");
		IRI leftPredicate = VF.createIRI("urn:join:hidden-alias-left");
		IRI rightPredicate = VF.createIRI("urn:join:hidden-alias-right");
		OrderedSource source = new OrderedSource(List.of(upper, lower), List.of(upper), leftPredicate, rightPredicate);
		BindingSet visible = new ListBindingSet(List.of("source"), lower);
		BindingSet input = BindingSetOrigin.optimizationInput(visible);
		Join original = new Join(
				new Projection(new StatementPattern(Var.of("leftSubject"), Var.of("leftPredicate", leftPredicate),
						Var.of("source")), new ProjectionElemList(new ProjectionElem("source", "x"))),
				statementPattern(rightPredicate));
		List<String> ordinary = representatives(evaluate(source, original.clone(), input), upper, lower);

		TupleExpr optimized = new QueryRoot(original.clone());
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		strategy.optimize(optimized, new EvaluationStatistics(), input);
		Join optimizedJoin = firstJoin(optimized);
		List<String> optimizedValues = representatives(evaluatePrepared(strategy, optimized, input), upper, lower);

		System.out.println("projection alias hidden request route"
				+ "\n  source parameter hidden=" + !input.hasBinding("source")
				+ "\n  source parameter authority=" + BindingSetOrigin.of(input).isRequest("source")
				+ "\n  invocation target x bound=" + input.hasBinding("x")
				+ "\n  natural algorithm=" + optimizedJoin.getAlgorithmName()
				+ "\n  ordinary bag=" + ordinary
				+ "\n  optimized bag=" + optimizedValues);

		assertThat(input.hasBinding("source")).isFalse();
		assertThat(BindingSetOrigin.of(input).isRequest("source")).isTrue();
		assertThat(input.hasBinding("x")).isFalse();
		assertThat(optimizedJoin.isMergeJoin()).isFalse();
		assertThat(optimizedValues).containsExactlyElementsOf(ordinary);
	}

	@Test
	void opaqueRowsOnlyNamesRemainUnknownInsideNestedJoin() {
		Literal value = VF.createLiteral("opaque-row");
		IRI expensivePredicate = VF.createIRI("urn:join:opaque-reorder-expensive");
		IRI cheapPredicate = VF.createIRI("urn:join:opaque-reorder-cheap");
		BindingSetAssignment opaque = opaqueUnorderedAssignment(value);
		opaque.setResultSizeEstimate(1_000_000);
		StatementPattern expensive = new StatementPattern(Var.of("expensiveSubject"),
				Var.of("predicate", expensivePredicate), Var.of("x"));
		StatementPattern cheap = new StatementPattern(Var.of("cheapSubject"),
				Var.of("predicate", cheapPredicate), Var.of("z"));
		expensive.setCardinality(100.0d);
		cheap.setCardinality(1.0d);
		Join original = new Join(new Join(opaque, expensive), cheap);
		TupleExpr plan = new QueryRoot(original);

		new QueryJoinOptimizer(new EvaluationStatistics()).optimize(plan, null, EmptyBindingSet.getInstance());
		Join optimized = firstJoin(plan);

		System.out.println("opaque rows-only nested-output schema characterization"
				+ "\n  declared header=" + opaque.getDeclaredBindingNames()
				+ "\n  reported possible names=" + opaque.getPossibleBindingNames()
				+ "\n  actual row name=x, value=" + value.stringValue()
				+ "\n  optimized tree:\n" + plan);

		assertThat(opaque).isExactlyInstanceOf(BindingSetAssignment.class);
		assertThat(opaque.getDeclaredBindingNames()).isEmpty();
		assertThat(opaque.getBindingNames()).isEmpty();
		assertThat(opaque.getPossibleBindingNames()).isEmpty();
		assertThat(opaque.hasRepeatableBindingSets()).isFalse();
		assertThat(joinLeaves(optimized)).contains(opaque, expensive, cheap);
	}

